package com.salespunch360.mobile.ui.account.accounting
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun AccountingScreen(initialMode:String,padding:PaddingValues,vm:AccountAccountingViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;LaunchedEffect(initialMode){vm.show(initialMode)};val rows=when(s.mode){"ledgers"->s.data.array("ledgerAccounts");"journals"->s.data.array("journalEntries");"period-locks"->s.data.array("accountingPeriodLocks");else->s.data.array("financialYears")};Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{Text(s.mode.replace('-',' ').replaceFirstChar{it.uppercase()},style=MaterialTheme.typography.headlineSmall,modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};if(s.mode in listOf("ledgers","period-locks"))FilledIconButton({vm.edit()}){Icon(Icons.Default.Add,"New")}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(rows){e->val x=e.jsonObject;ListItem(headlineContent={Text(x.str("name").ifBlank{x.str("journalNumber").ifBlank{x.str("eventType")}})},supportingContent={Text(x.str("accountClass").ifBlank{x.str("status")})},trailingContent={Text(x.str("lockedThrough").take(10))})}}};if(s.editing)AccountingEditor(s.mode,s.data,{vm.edit(false)},vm::save)}
@Composable private fun AccountingEditor(mode:String,data:JsonObject,close:()->Unit,save:(JsonObject)->Unit){var name by remember{mutableStateOf("")};var date by remember{mutableStateOf(java.time.LocalDate.now().toString())};var amount by remember{mutableStateOf("")};var reason by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("New ${mode.replace('-',' ')}")},text={Column{if(mode=="ledgers")OutlinedTextField(name,{name=it},label={Text("Account name")})else{OutlinedTextField(date,{date=it},label={Text("Date")});OutlinedTextField(amount,{amount=it},label={Text(if(mode=="period-locks")"Financial year id" else "Debit/Credit amount")});OutlinedTextField(reason,{reason=it},label={Text("Reason / narration")})}}},confirmButton={Button(onClick={save(buildJsonObject{if(mode=="ledgers"){put("code","MOB-${System.currentTimeMillis()}");put("name",name);put("accountClass","EXPENSE");put("normalBalance","DEBIT");put("allowPosting",true)}else if(mode=="period-locks"){put("financialYearId",amount);put("lockedThrough",date);put("reason",reason)}})}){Text("Validate on server")}},dismissButton={TextButton(close){Text("Cancel")}})}
